import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';
import { Container, Form } from 'react-bootstrap';
import DocumentViewer from '../Components/DocumentViewer/DocumentViewer';
import EvaluationUploader from '../Components/EvaluationUploader/EvaluationUploader';
import GradeReport from '../Components/GradeReport/GradeReport';
import NewsFeed from '../Components/NewsFeed/NewsFeed';

// Puedes reemplazar esto luego con un fetch a base de datos
const mockCourses = [
  { id: 1, name: 'Matemáticas' },
  { id: 2, name: 'Historia' },
  { id: 3, name: 'Programación' },
];

const StudentDashboard = () => {
  const location = useLocation();
  const user = location.state?.user;

  const [selectedCourseId, setSelectedCourseId] = useState(null);

  const handleCourseChange = (e) => {
    const courseId = parseInt(e.target.value);
    setSelectedCourseId(courseId);
  };

  const selectedCourse = mockCourses.find(course => course.id === selectedCourseId);

  return (
    <Container className="mt-4 text-white">
      <h2>Bienvenido, {user?.name || 'Estudiante'}</h2>
      <hr />

      <Form.Group controlId="courseSelector" className="mb-3">
        <Form.Label>Selecciona un curso:</Form.Label>
        <Form.Select onChange={handleCourseChange} value={selectedCourseId || ''}>
          <option value="">-- Elige un curso --</option>
          {mockCourses.map(course => (
            <option key={course.id} value={course.id}>
              {course.name}
            </option>
          ))}
        </Form.Select>
      </Form.Group>

      {selectedCourse && (
        <>
          <h4>Vista del curso: {selectedCourse.name}</h4>
          <hr />

          {selectedCourse.name === 'Matemáticas' && (
            <>
              <DocumentViewer user={user} />
              <GradeReport user={user} />
            </>
          )}

          {selectedCourse.name === 'Historia' && (
            <>
              <EvaluationUploader user={user} />
              <NewsFeed />
            </>
          )}

          {selectedCourse.name === 'Programación' && (
            <>
              <DocumentViewer user={user} />
              <EvaluationUploader user={user} />
              <GradeReport user={user} />
            </>
          )}
        </>
      )}
    </Container>
  );
};

export default StudentDashboard;
